/**
 * 「这一页什么都没有」的那一句话，**两个页面问同一个函数**。
 *
 * ── 为什么它不是两句写在各自页面里的话 ────────────────────────────────────────
 *
 * 「这里什么都没有」与「没有一个匹配的」在屏幕上长得一样，而它们指向两种相反的修法：
 * 一种靠写一条，另一种靠撤掉一个筛子。按 `filtering` 一个布尔去猜，会在读者真正
 * 所处的那种状态上答错——**空白文档 + 搜索框里已经有一个词**，屏上说「没有匹配的结果，
 * 清空搜索看看」，而那个搜索从来不是把这一页清空的原因。
 *
 * 两个页面（清单与日程）对同一份文档问同一个问题，所以答案只有一处：拿到同一份计数、
 * 同一个查询、同一个时钟，说同一句话。抄一份的代价不是那几行——是**两个页面会在
 * 某一天对同一份空文档说两句不同的话**，而屏上不会有人说一句话。
 *
 * 被一个日期筛空时还要说出那个日期：「没有匹配的结果」在读者刚按了 9 号之后是一句
 * 没用的话，该出现的是「9 号没有东西」——**一句话里带着他刚按下的那个选择**，
 * 而「换个日期」这四个字也真的可做：日历就在旁边。
 */
import type { ItemRecord } from '../../../core/item.ts';
import type { ItemQuery } from '../../../core/item-view.ts';
/**
 * 这一页该说的那句空话。
 * @param items - 这份文档里的每一行（页面自己不过滤）。
 * @param query - 搜索框里那个查询。
 * @param now - 阅读时钟，日期读数要以它为准。
 * @returns 那句话。
 */
export declare function nothingToShowOf(items: readonly ItemRecord[], query: ItemQuery, now: number): string;
